export const isProfileId = (v: unknown): v is ProfileId =>
  typeof v === 'string' && (PROFILE_IDS as readonly string[]).includes(v)

/** A stored id, or the default when it is unknown (a profile from a newer build, say). */
export const profileOf = (id: string | undefined): Profile =>
  PROFILES[isProfileId(id) ? id : 'default']

/**
 * The layout a destination gets. `auto` keeps today's behaviour (lists only when the speaker
 * enumerates) everywhere except email, documents and notes, where longer text also gets a
 * paragraph break at each new topic.
 */
export function resolveLayout(layout: Layout | undefined, category: AppCategory): ResolvedLayout {
  if (layout && layout !== 'auto') return layout
  return category === 'email' || category === 'document' || category === 'notes'
    ? 'balanced'
    : 'lists'
}

/**
 * The line the formatting prompt gets for a layout; empty for `lists`, the behaviour the system
 * prompt already describes, so most prompts are byte-identical to the ones before profiles.
 */
export function layoutLine(layout: ResolvedLayout): string {
  switch (layout) {
    case 'minimal':
      return 'Layout: running text; no list or line break the speaker did not dictate.'
    case 'balanced':
      return 'Layout: paragraphs. In text of four or more sentences, leave a blank line where the speaker moves to a new topic. A counted enumeration ("first..., second...") is still a list, one item per line.'
    case 'structured':
      return "Layout: structured. Leave a blank line where the speaker moves to a new topic. Three or more parallel items or steps said in a row go one per line as a list, even if not counted, each in the speaker's own words. Two items stay in the sentence; sentences that are not a series, and pieces of one sentence cut at pauses, stay prose."
    default:
      return ''
  }
}

export function grammarLine(grammar: Grammar | undefined): string {
  return grammar === 'as-spoken'
    ? "Grammar: as spoken. Keep the speaker's own wording and grammar, even where it is informal; fix only punctuation, capitalization, fillers, stutters and spoken commands."
    : ''
}

/** Frequent message openers that `COMMON_WORDS` leaves out (it skips some short function words). */
const CASUAL_WORDS = new Set(
  "hey hi hello ok okay lol lmao btw omg haha yep yup nope yeah ya a an in do so my see good way day will to of or if on as at by up go no oh um don't doesn't didn't won't can't isn't aren't wasn't let's that's it's what's there's here's".split(
    ' '
  )
)

const lowerable = (lower: string): boolean =>
  CASUAL_WORDS.has(lower.replace(/’/g, "'")) || COMMON_WORDS.has(lower.replace(/['’].*$/, ''))

const SENTENCE_START =
  /((?:^|\n)\s*(?:[-*•]\s+|\d{1,3}[.)]\s+)?|[.!?]["')\]]*\s+)(\p{Lu}[\p{Ll}'’]*)(?![\p{L}\p{N}])/gu

/** Capitalized after a word or a comma somewhere in `text`: a name ("Will", "May"), not a sentence start. */
const capitalizedMidSentence = (word: string, text: string): boolean =>
  new RegExp(`[\\p{L}\\p{N},;:]\\s+${word}(?![\\p{L}'’])`, 'u').test(text)

/**
 * Lower-case casing, the "very casual" chat style: sentence starts lose their capital and a
 * one-line message loses its final period. Only frequent words are lowered (`COMMON_WORDS`), so
 * names, "I" and acronyms keep their capitals, as do a word the text capitalizes mid-sentence
 * and the user's dictionary words (`keep`); "?" and "!" stay. Runs on the device after
 * formatting, so it needs no model and costs microseconds.
 */
export function applyCasing(
  text: string,
  casing: Casing | undefined,
  category?: AppCategory,
  keep: readonly string[] = []
): string {
  if (casing !== 'lowercase' || category === 'code' || category === 'terminal') return text
  let out = text.replace(SENTENCE_START, (m, sep: string, word: string) => {
    const lower = word.toLowerCase()
    if (word === 'I' || /^i['’]/.test(lower) || !lowerable(lower)) return m
    if (keep.includes(word) || capitalizedMidSentence(word, text)) return m
    return sep + lower
  })
  const trimmed = out.replace(/\s+$/u, '')
  if (!trimmed.includes('\n') && /[^.]\.$/u.test(trimmed) && !/\b\p{L}\.\p{L}\.$/u.test(trimmed))
    out = trimmed.slice(0, -1) + out.slice(trimmed.length)
  return out
}

/** "Hi Sam," / "Dear Ms. Alvarez," alone on the first line. */
const GREETING_LINE =
  /^((?:hi|hello|hey|dear|good (?:morning|afternoon|evening))\b[^\n,!?]{0,40},)[ \t]*\n\s*/iu

/**
 * Line breaks the model added on its own (to text with no list), kept only where a layout allows
 * them: a blank line after a sentence end stays a paragraph break; a single newline, or a blank
 * line inside a sentence, is joined back with a space.
 */
export function keepParagraphs(text: string): string {
  // A greeting on its own line opens the letter: a paragraph of its own.
  const paragraphs = text
    .replace(GREETING_LINE, '$1\n\n')
    .split(/[ \t]*\n[ \t]*\n\s*/u)
    .map((p) => p.replace(/[ \t]*\n[ \t]*/gu, ' ').trim())
    .filter(Boolean)
  let out = paragraphs[0] ?? ''
  for (let i = 1; i < paragraphs.length; i++)
    out +=
      /[.!?:…]["'’”)\]]*$/u.test(paragraphs[i - 1]) ||
      (i === 1 && GREETING_LINE.test(`${paragraphs[0]}\n`))
        ? `\n\n${paragraphs[i]}`
        : ` ${paragraphs[i]}`
  return out
}

/** Is `layout` one that lets the model start paragraphs by itself? */
export const addsParagraphs = (layout: ResolvedLayout): boolean =>
  layout === 'balanced' || layout === 'structured'
